"use strict";(globalThis.webpackChunkmy_website||=[]).push([[93840],{64108(e){e.exports=JSON.parse('{"slug":"plinth","title":"Plinth","short":"The high-level Haskell-embedded language Cardano developers use to write on-chain validators that compile to Plutus Core.","category":"smart-contracts","aliases":["Plutus Tx"],"mentalModel":null,"related":["plutus","plutus-core","haskell","smart-contract","validator","aiken"],"sources":[],"link":null,"level":"intermediate","body":"A subset of Haskell used to write Plutus smart contracts. Plinth (formerly called Plutus Tx) is Input Output\'s recommended toolchain for Cardano on-chain development. Developers write validators in Haskell with the restrictions Plinth enforces, then the compiler turns the result into Plutus Core for the on-chain runtime.\\n\\nPlinth lives alongside alternatives like Aiken, which targets the same Plutus Core runtime but offers a different language and developer experience."}')}}]);